      options: { sessionId },
      agentLoop: resumedLoop,
      deps: {
        ...baseStore,
        sessionExists: () => true,
        readSessionHostResumeState: () => verifiedResume(sessionId),
      },
      inputGen: async function* () {
        yield JSON.stringify({ type: "user", text: "continue" }) + "\n";
      },
    });
