/**
 * Canonicalize the part of a tool request that is classified and shown to the
 * user for approval. Keeping this in one place prevents the safety classifier
 * and the permission prompt from silently reasoning about different inputs.
 */

function quoteArgvToken(value) {
  const token = String(value);
  if (token && !/[\s|;&"'\\]/u.test(token)) return token;
  return `"${token.replace(/\\/gu, "\\\\").replace(/"/gu, '\\"')}"`;
}

export function normalizePermissionRequest({ tool, args } = {}) {
  const normalizedArgs = args && typeof args === "object" ? args : {};
  const command =
    typeof normalizedArgs.command === "string"
      ? normalizedArgs.command
      : Array.isArray(normalizedArgs.argv)
        ? normalizedArgs.argv.map(quoteArgvToken).join(" ")
        : "";
  const source = String(
    normalizedArgs.path ??
      normalizedArgs.file_path ??
      normalizedArgs.source ??
      normalizedArgs.from ??
      "",
  );
  const destination = String(
    normalizedArgs.destination ??
      normalizedArgs.new_path ??
      normalizedArgs.to ??
      "",
  );
  const detail =
    command ||
    (source && destination
      ? `${source} -> ${destination}`
      : source || destination);

  return Object.freeze({
    tool: String(tool || "unknown").trim() || "unknown",
    args: normalizedArgs,
    command,
    source,
    destination,
    detail,
  });
}

import "../helpers/test-model-egress.js";
/**
 * Interactive approvals (--interactive-approvals; chat-panel Approve/Deny) —
 * confirm-tier decisions become an approval_request / {"type":"approval"}
 * round-trip on the duplex pipes instead of headless fail-closed:
 *   - the blocked tool resolves with the user's verdict (approve / deny)
 *   - timeout (CC_APPROVAL_TIMEOUT_MS) and stdin-close fail closed
 *   - the ApprovalGate confirmer is swapped only when the flag is on
 * The pump handles approval verdicts immediately, mid-turn, like interrupts.
 */
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { PassThrough } from "node:stream";
import {
  runAgentHeadlessStream,
  parseInputEvent,
} from "../../src/runtime/headless-stream.js";
import { approvalBindingDigest } from "../../src/lib/agent-authority.js";
import {
  APPROVAL_GRANTS_EVENT,
  approvalPermissionForContext,
} from "../../src/lib/approval-grant-ledger.js";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function verifiedResume(sessionId) {
  return {
    snapshot: {
      schema: "chainlesschain.session-host-snapshot/v1",
      schemaVersion: 1,
      sessionId,
      verified: true,
      revision: `sha256:${"b".repeat(64)}`,
    },
    messages: [],
    recovery: {
      sessionId,
      records: [],
      unsettled: [],
      incidents: [],
      adjudications: [],
      replayDenied: [],
      verified: true,
      headHash: "a".repeat(64),
      recoveryDigest: `sha256:${"c".repeat(64)}`,
      remediation: null,
    },
  };
}

describe("parseInputEvent — approval verdicts", () => {
  it("parses approve/deny and rejects malformed ones", () => {
    expect(
      parseInputEvent('{"type":"approval","id":"appr-1","approve":true}'),
    ).toEqual({
      approval: {
        id: "appr-1",
        approve: true,
        decision: { kind: "acceptOnce" },
        structured: false,
        invalidReason: null,
        binding: null,
      },
    });
    expect(
      parseInputEvent('{"type":"approval","id":"appr-2","approve":"yes"}'),
    ).toEqual({
      approval: {
        id: "appr-2",
        approve: false,
        decision: { kind: "decline", reason: "Legacy boolean denial" },
        structured: false,
        invalidReason: null,
        binding: null,
      },
    }); // strict boolean
