/**
 * Independent regression coverage for packages/cli/src/lib/permission-request.js.
 *
 * The module exports a single pure function, normalizePermissionRequest, that
 * canonicalizes the part of a tool request that is classified and shown for
 * approval. Because the canonicalization result is a deterministic frozen
 * projection of the request context, a "late" re-invocation with the same input
 * must reproduce exactly the same normalized request (only the original request
 * is represented) and the frozen result cannot be silently mutated to repoint
 * the request. These controls exercise every independent branch of the
 * exported function.
 */
import { describe, it, expect } from "vitest";
import { normalizePermissionRequest } from "../src/lib/permission-request.js";

describe("normalizePermissionRequest", () => {
  it("normalizes the tool name (trim) and defaults to unknown", () => {
    // positive: whitespace-padded name is trimmed
    expect(normalizePermissionRequest({ tool: "  run_shell  " }).tool).toBe(
      "run_shell",
    );
    // negative (only tool changed): absent / blank falls back to "unknown"
    expect(normalizePermissionRequest().tool).toBe("unknown");
    expect(normalizePermissionRequest({ tool: "   " }).tool).toBe("unknown");
  });

  it("builds the command from a string command, else empty when neither is present", () => {
    // positive: explicit string command is taken verbatim
    expect(
      normalizePermissionRequest({
        tool: "run_shell",
        args: { command: "ls -la" },
      }).command,
    ).toBe("ls -la");
    // negative (only command/argv removed): no command and no argv -> ""
    expect(
      normalizePermissionRequest({ tool: "run_shell", args: {} }).command,
    ).toBe("");
  });

  it("joins argv into a command, quoting only special tokens", () => {
    // positive: a plain token is kept unquoted
    expect(
      normalizePermissionRequest({ args: { argv: ["echo", "hi"] } }).command,
    ).toBe("echo hi");
    // negative (only token specialness changed): whitespace / shell-meta tokens
    // are shell-quoted, so they cannot inject a separate argument
    expect(
      normalizePermissionRequest({
        args: { argv: ["echo", "hello world", "a&b"] },
      }).command,
    ).toBe('echo "hello world" "a&b"');
  });

  it("prefers path over file_path/source when resolving the source", () => {
    // positive: path wins over all source aliases
    expect(
      normalizePermissionRequest({
        args: { path: "/a", file_path: "/b", source: "/c" },
      }).source,
    ).toBe("/a");
    // negative (only path removed): next alias file_path is used
    expect(
      normalizePermissionRequest({
        args: { file_path: "/b", source: "/c" },
      }).source,
    ).toBe("/b");
  });

  it("prefers destination over new_path/to and composes detail", () => {
    // positive: destination wins; detail becomes "source -> destination"
    const req = normalizePermissionRequest({
      args: { path: "/a", destination: "/b", new_path: "/x" },
    });
    expect(req.destination).toBe("/b");
    expect(req.detail).toBe("/a -> /b");
    // negative (only destination removed): next alias "to" is used
    expect(
      normalizePermissionRequest({ args: { source: "/a", to: "/z" } }).detail,
    ).toBe("/a -> /z");
  });

  it("freezes the result and is deterministic (re-invocation yields the same request)", () => {
    const req = normalizePermissionRequest({ tool: "run_shell", args: null });
    expect(Object.isFrozen(req)).toBe(true);
    expect(req.args).toEqual({}); // non-object args fall back to {}
    // only the original request is represented: identical input reproduces it
    expect(
      normalizePermissionRequest({ tool: "run_shell", args: null }),
    ).toEqual(req);
    // a late caller cannot repoint the request to another tool
    expect(() => {
      req.tool = "hijacked_tool";
    }).toThrow();
  });
});

